package store_test
import("context";"database/sql";"encoding/json";"path/filepath";"testing";"time";"github.com/aoagents/agent-orchestrator/backend/internal/domain";"github.com/aoagents/agent-orchestrator/backend/internal/storage/sqlite";adapter "github.com/aoagents/agent-orchestrator/backend/internal/storage/sqlite/store")
func TestOfflineBodyExpiryKeepsDedupeAndControlProof(t *testing.T){
 ctx:=context.Background();dir:=t.TempDir();s,e:=sqlite.Open(dir);if e!=nil{t.Fatal(e)};defer s.Close();seedProject(t,s,"body-owned");rec:=sampleRecord("body-owned");rec.Mode=domain.SessionModeChat;session,e:=s.CreateSession(ctx,rec);if e!=nil{t.Fatal(e)};conv,e:=s.CreateConversation(ctx,"body-owned-conv",domain.ConversationScopeSession,"body-owned",session.ID,histClock);if e!=nil{t.Fatal(e)}
 db,e:=sql.Open("sqlite",filepath.Join(dir,"ao.db"));if e!=nil{t.Fatal(e)};defer db.Close();for _,v:=range []struct{key,method string}{{"KEEP-DEDUPE","message.delta"},{"KEEP-CONTROL","turn.completed"}}{if _,e=db.Exec(`INSERT INTO conversation_provider_events(conversation_id,session_id,provider_event_id,method,payload_json,received_at)VALUES(?,?,?,?,?,?)`,conv.ID,session.ID,v.key,v.method,`{"text":"OLD-BODY","error":null,"usage":{"input":2}}`,histClock);e!=nil{t.Fatal(e)}}
 cap:=s.HistoryRetentionCapability();o:=adapter.DefaultHistoryMaintenanceOptions();o.Retention=48*time.Hour;o.WriteBudget=time.Second;r:=adapter.HistoryMaintenanceRequest{Stage:"raw",Cutoff:time.Now().UTC().Add(-48*time.Hour).Format(time.RFC3339Nano),DatabaseDevice:cap["dbDevice"].(uint64),DatabaseInode:cap["dbInode"].(uint64)}
 result,e:=s.MaintainHistorySnapshotBatch(ctx,r,o,time.Now().UTC());if e!=nil||result.Compacted!=1||result.Markers!=0||!result.Committed{t.Fatalf("body %+v %v",result,e)}
 var payload string;db.QueryRow(`SELECT payload_json FROM conversation_provider_events WHERE provider_event_id='KEEP-DEDUPE'`).Scan(&payload);var value map[string]any;if e=json.Unmarshal([]byte(payload),&value);e!=nil||value["text"]!=""||value["error"]!=nil||value["usage"].(map[string]any)["input"].(float64)!=2{t.Fatal("identity payload proof changed",e)}
 db.QueryRow(`SELECT payload_json FROM conversation_provider_events WHERE provider_event_id='KEEP-CONTROL'`).Scan(&payload);json.Unmarshal([]byte(payload),&value);if value["text"]!="OLD-BODY"{t.Fatal("control body unexpectedly cleared")}
}
